True from collections import Counter

def transform(grid):
    counts = Counter(value for row in grid for value in row if value != 0)
    color = counts.most_common(1)[0][0]
    patterns = {
        1: [[0, 0, 8], [8, 8, 0], [0, 8, 0]],
        2: [[0, 0, 0], [8, 8, 8], [0, 0, 0]],
        3: [[0, 8, 8], [0, 8, 0], [0, 8, 0]],
    }
    return patterns[color]
